    coach: { intro: [{ speaker: 'guide', text: 'Trace this journey through places that were already people’s homes.', pose: 'talk' }, { speaker: 'kid', text: 'I’ll place each clue and compare what the travelers and communities wanted.' }], reactions: { retry: { text: 'Check the river, village, or coast named in the source before placing the clue.', pose: 'think' }, milestone: { text: 'Your route clues are placed. Compare the expedition’s goals with Native choices.', pose: 'talk' }, complete: { text: 'You explained a journey while recognizing the knowledge and decisions of people already there.', pose: 'cheer' } } },
